const baseEmail = $('Get Full Email').item?.json || {};
const analyzer = $('Execute Context Builder').item?.json || {};
const classification = analyzer.classification || {};
const context = analyzer || {};
const email = { ...baseEmail, classification };
const subject = baseEmail.subject || baseEmail.Subject || 'Formalności';
return {
  json: {
    response_guidance: analyzer.response_guidance || {},
    email,
    context,
    classification,
    route_intent: 'formalnosci',
    template_type: 'formalnosci',
    draft: { draft_subject: `RE: ${subject}` },
  },
};

const handler = $('Merge Handler Outputs').item?.json || {};
const rg = $input.first().json || {};
const routeIntent = String(handler.route_intent || '').toLowerCase();
const isFormalnosci = routeIntent === 'formalnosci' || routeIntent === 'confirmation';

let subj = handler.draft?.draft_subject || ('RE: ' + (handler.email?.subject || handler.email?.Subject || ''));
if (!isFormalnosci && rg.draft_subject) subj = rg.draft_subject;

const FORMALNOSCI_BODY = 'Dzień dobry,\n\nPotwierdzam odbiór wiadomości. Dziękuję.\n\nZ poważaniem,\nTomasz Szwecki\nImpresariat Koncertowy';

let body = rg.draft_body;
if (isFormalnosci) {
  body = FORMALNOSCI_BODY;
} else if (!body) {
  body = 'Dzień dobry,\n\nDziękuję za wiadomość. Wrócę z odpowiedzią.\n\nZ poważaniem,\nTomasz Szwecki\nImpresariat Koncertowy';
}

const draft = { draft_subject: subj, draft_body: body };
return { json: { ...handler, draft } };

const item = $input.first().json || {};
const cls = item.classification || {};
const intent = String(cls.intent || '').toLowerCase();
const LABELS = { zapytanie_o_impreze:'Label_1164233469838029683', dostepnosc_artysty:'Label_2392364100075658386', wspolpraca_wykonawca:'Label_7987774113567348098', formalnosci:'Label_1927380376375892524', confirmation:'Label_1927380376375892524', follow_up:'Label_6056553363396268183', inne:'Label_2258360176253958758', new_inquiry:'Label_1164233469838029683', artist_response:'Label_7987774113567348098' };
const label_id = cls.label_id || LABELS[intent] || LABELS.inne || '';
return { json: { ...item, classification: { ...cls, label_id } } };

const item = $input.first().json || {};

function decodeBase64Url(input) {
  if (!input || typeof input !== 'string') return '';
  const normalized = input.replace(/-/g, '+').replace(/_/g, '/');
  const pad = normalized.length % 4;
  const padded = pad ? normalized + '='.repeat(4 - pad) : normalized;
  try {
    return Buffer.from(padded, 'base64').toString('utf8');
  } catch {
    return '';
  }
}

function stripHtml(html) {
  if (!html) return '';
  return html
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function collectTextFromPayload(payload) {
  if (!payload) return '';

  if (payload.body && payload.body.data) {
    const mime = (payload.mimeType || '').toLowerCase();
    const text = decodeBase64Url(payload.body.data);
    if (mime.includes('text/plain')) return text;
    if (mime.includes('text/html')) return stripHtml(text);
  }

  if (Array.isArray(payload.parts)) {
    const plainParts = [];
    const htmlParts = [];

    for (const part of payload.parts) {
      const text = collectTextFromPayload(part);
      const mime = (part.mimeType || '').toLowerCase();
      if (!text) continue;
      if (mime.includes('text/plain')) plainParts.push(text);
      else if (mime.includes('text/html')) htmlParts.push(text);
      else plainParts.push(text);
    }

    if (plainParts.length) return plainParts.join('\n');
    if (htmlParts.length) return htmlParts.join('\n');
  }

  return '';
}

function messageToText(msg) {
  const textPlain = msg.textPlain || msg.text || '';
  const textHtml = stripHtml(msg.textHtml || '');
  const payloadText = collectTextFromPayload(msg.payload);
  const snippet = msg.snippet || '';

  return [textPlain, payloadText, textHtml, snippet]
    .map((v) => (typeof v === 'string' ? v.trim() : ''))
    .find((v) => v.length > 0) || '';
}

const content = messageToText(item);
const senderEmail = item.from || item.From || '';
const subject = item.subject || item.Subject || '';

let threadHistory = '';
if (Array.isArray(item.messages) && item.messages.length > 0) {
  threadHistory = item.messages
    .map((m, idx) => {
      const from = m.from || m.From || '';
      const subj = m.subject || m.Subject || '';
      const body = messageToText(m);
      return `Message ${idx + 1}\nFrom: ${from}\nSubject: ${subj}\nBody:\n${body}`;
    })
    .join('\n\n---\n\n')
    .slice(0, 12000);
}

return {
  json: {
    ...item,
    content,
    sender_email: senderEmail,
    subject,
    thread_history: threadHistory,
    knowledge_context: item.knowledge_context || '',
  },
};

const item = $input.first().json || {};
const cls = item.classification || {};
const ctx = item.context || item;

const intent = String(cls.intent || '').toLowerCase();
const senderRole = String(cls.sender_role || '').toLowerCase();

const email = $('Get Full Email').item?.json || {};
const senderRaw = String(email.from || email.From || ctx.client_email || '').toLowerCase();
const subject = String(email.subject || email.Subject || '').toLowerCase();
const snippet = String(email.snippet || '').toLowerCase();
const prepContent = String($('Prepare Analyzer Input').item?.json?.content || '').toLowerCase();
const content = (prepContent || snippet);

const formalnosciKeywords = ['umowa', 'umowy', 'umow', 'skan', 'przesyłam', 'przesyła', 'prześlę', 'faktura', 'przelew', 'poczta', 'załącznik', 'przekaże', 'gotowa', 'gotowy', 'przesłana', 'przesłany', 'przesłane'];
const textToCheck = (content + ' ' + subject).toLowerCase();
const isFormalnosciByContent = formalnosciKeywords.some((kw) => textToCheck.includes(kw));

const nonBusinessPatterns = [
  'google cloud',
  'cloudplatform-noreply',
  'noreply',
  'no-reply',
  'security best practices',
  'action advised',
  'my console',
  'account alert',
  'policy update',
];

const isSystemLike = nonBusinessPatterns.some((p) =>
  senderRaw.includes(p) || subject.includes(p) || snippet.includes(p)
);

let route_intent = 'new_inquiry';

if (isSystemLike || senderRole === 'other' || intent === 'other') {
  route_intent = 'ignore';
} else if (isFormalnosciByContent) {
  route_intent = 'formalnosci';
} else if (senderRole === 'artist') {
  route_intent = 'artist_response';
} else if (['follow_up', 'followup', 'reply', 'response', 'confirmation'].includes(intent)) {
  route_intent = 'follow_up';
} else if (['artist_response', 'availability_response', 'availability_confirmation'].includes(intent)) {
  route_intent = 'artist_response';
} else if (['new_inquiry', 'inquiry', 'booking_request'].includes(intent)) {
  route_intent = 'new_inquiry';
} else if (['formalnosci', 'confirmation', 'formalności'].includes(intent)) {
  route_intent = 'formalnosci';
}

const LABELS = { formalnosci:'Label_1927380376375892524', confirmation:'Label_1927380376375892524', new_inquiry:'Label_1164233469838029683', follow_up:'Label_6056553363396268183', artist_response:'Label_7987774113567348098', inne:'Label_2258360176253958758' };
const label_id = item.classification?.label_id || LABELS[route_intent] || '';
return {
  json: {
    ...item,
    classification: { ...item.classification, label_id },
    route_intent,
    route_reason: isFormalnosciByContent ? 'content_keywords_formalnosci' : (isSystemLike ? 'system_or_non_business' : 'intent_based'),
  },
};

const item = $input.first().json || {};
const draft = item.draft || {};
const cls = item.classification || {};
const routeIntent = String(item.route_intent || '').toLowerCase();
const senderRole = String(cls.sender_role || '').toLowerCase();

let subject = String(draft.draft_subject || '').trim();
let body = String(draft.draft_body || '')
  .replace(/\\n/g, '\n')
  .replace(/\r\n/g, '\n')
  .trim();

if (!subject) {
  const sourceSubject = item.email?.subject || item.email?.Subject || item.subject || 'Wiadomość';
  subject = `RE: ${sourceSubject}`;
}

if (!body) {
  body =
    'Dzień dobry,\n\n' +
    'Dziękuję za wiadomość. Wrócę z odpowiedzią najszybciej jak to możliwe.\n\n' +
    'Z poważaniem,\nTomasz Szwecki\nImpresariat Koncertowy';
}

// Guardrail: when artist confirms availability, avoid sending client-intake questions.
if (senderRole === 'artist' && routeIntent === 'artist_response') {
  const lower = body.toLowerCase();
  if (
    lower.includes('budżet') ||
    lower.includes('lokalizacj') ||
    lower.includes('preferowanych artyst') ||
    lower.includes('termin')
  ) {
    body =
      'Dzień dobry,\n\n' +
      'Dziękuję za potwierdzenie dostępności i przesłane informacje. Potwierdzam odbiór i wrócę z dalszymi ustaleniami.\n\n' +
      'Z poważaniem,\nTomasz Szwecki\nImpresariat Koncertowy';
  }
}

function escapeHtml(s) {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const draft_body_html = body
  .split(/\n\n+/)
  .map((p) => p.trim())
  .filter(Boolean)
  .map((p) => `<p>${escapeHtml(p)}</p>`)
  .join('');

return {
  json: {
    ...item,
    draft: {
      ...draft,
      draft_subject: subject,
      draft_body: body,
      draft_body_html,
    },
    audit: {
      formatted: true,
      route_intent: routeIntent,
    },
  },
};

const email = $('Get Full Email').item?.json || {};
const analyzer = $('Execute Context Builder').item?.json || {};

return {
  json: {
    ignored: true,
    reason: 'non_business_or_system_message',
    from: email.from || email.From || '',
    subject: email.subject || email.Subject || '',
    classification: analyzer.classification || {},
  },
};
